package com.hiresense.security;
import com.hiresense.domain.AppUser; import com.hiresense.repository.AppUserRepository; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service public class AppUserDetailsService implements UserDetailsService { private final AppUserRepository repo; public AppUserDetailsService(AppUserRepository r){repo=r;} public UserDetails loadUserByUsername(String email)throws UsernameNotFoundException{AppUser u=repo.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Invalid credentials"));return User.withUsername(u.getEmail()).password(u.getPasswordHash()).disabled(!u.isActive()).authorities(u.getRoles().stream().map(r->"ROLE_"+r.getName().name()).toArray(String[]::new)).build();} }
